<?php defined('BASEPATH') OR exit('No direct script access allowed');$types=['service_review'=>'Ulasan pelayanan','book_request'=>'Usul buku','digital_content'=>'Usul konten digital','facility'=>'Fasilitas / pojok baca','feature'=>'Usul fitur','complaint'=>'Keluhan','other'=>'Lainnya'];$statuses=['pending'=>'Menunggu','reviewing'=>'Ditinjau','planned'=>'Direncanakan','resolved'=>'Selesai','declined'=>'Tidak ditindaklanjuti'];$colors=['pending'=>'bg-yellow-lt text-yellow','reviewing'=>'bg-azure-lt text-azure','planned'=>'bg-purple-lt text-purple','resolved'=>'bg-green-lt text-green','declined'=>'bg-secondary-lt text-secondary'];$query=$_GET;unset($query['page']);$pageurl=function($p)use($query){return base_url('patron-feedback?'.http_build_query(array_merge($query,['page'=>$p])));}; ?>
<?php $public_voice_url=base_url('suara-pemustaka'); ?>
<div class="page-header d-print-none"><div class="container-xl"><div class="row g-2 align-items-center"><div class="col"><div class="page-pretitle">Partisipasi Publik</div><h1 class="page-title">Suara Pemustaka</h1></div><div class="col-auto btn-list"><button class="btn btn-outline-primary" type="button" data-bs-toggle="modal" data-bs-target="#patron-feedback-qr"><i class="ti ti-qrcode me-1"></i>QR Form</button><a class="btn btn-outline-primary" target="_blank" href="<?=$public_voice_url;?>"><i class="ti ti-external-link me-1"></i>Buka Form Publik</a></div></div></div></div>
<div class="modal modal-blur fade" id="patron-feedback-qr" tabindex="-1" aria-labelledby="patron-feedback-qr-title" aria-hidden="true"><div class="modal-dialog modal-sm"><div class="modal-content"><div class="modal-header"><h5 id="patron-feedback-qr-title" class="modal-title">QR Suara Pemustaka</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body text-center"><div id="patron-feedback-qr-target" class="d-inline-block p-2 bg-white border rounded-3" data-qr="<?=html_escape($public_voice_url);?>"></div><p class="small text-secondary mt-3 mb-2">Scan untuk membuka form ulasan layanan, usul buku, konten, dan saran perpustakaan.</p><input id="patron-feedback-qr-url" class="form-control form-control-sm text-center" readonly value="<?=html_escape($public_voice_url);?>"></div><div class="modal-footer"><button class="btn btn-outline-primary" type="button" id="copy-patron-feedback-qr"><i class="ti ti-copy me-1"></i>Salin Link</button><button class="btn btn-primary" type="button" id="download-patron-feedback-qr"><i class="ti ti-download me-1"></i>Unduh QR</button></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script>document.addEventListener('DOMContentLoaded',function(){var t=document.getElementById('patron-feedback-qr-target'),u=document.getElementById('patron-feedback-qr-url');if(t&&window.QRCode){new QRCode(t,{text:t.getAttribute('data-qr'),width:240,height:240,colorDark:'#062b5d',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});}var c=document.getElementById('copy-patron-feedback-qr');if(c&&u)c.addEventListener('click',function(){u.select();u.setSelectionRange(0,99999);if(navigator.clipboard){navigator.clipboard.writeText(u.value);}else{document.execCommand('copy');}c.innerHTML='<i class="ti ti-check me-1"></i>Tersalin';setTimeout(function(){c.innerHTML='<i class="ti ti-copy me-1"></i>Salin Link';},1800);});var d=document.getElementById('download-patron-feedback-qr');if(d&&t)d.addEventListener('click',function(){var canvas=t.querySelector('canvas');if(!canvas)return;var link=document.createElement('a');link.href=canvas.toDataURL('image/png');link.download='qr-suara-pemustaka.png';link.click();});});</script>
<div class="page-body"><div class="container-xl"><?php if($this->session->flashdata('success')):?><div class="alert alert-success"><?=html_escape($this->session->flashdata('success'));?></div><?php endif;?><?php if($this->session->flashdata('error')):?><div class="alert alert-danger"><?=html_escape($this->session->flashdata('error'));?></div><?php endif;?><div class="row row-cards mb-3"><div class="col-6 col-lg-3"><div class="card card-sm"><div class="card-body"><div class="small text-secondary">Menunggu</div><div class="h2 mb-0 text-yellow"><?=number_format($stats['pending'],0,',','.');?></div></div></div></div><div class="col-6 col-lg-3"><div class="card card-sm"><div class="card-body"><div class="small text-secondary">Ditinjau</div><div class="h2 mb-0 text-azure"><?=number_format($stats['reviewing'],0,',','.');?></div></div></div></div><div class="col-6 col-lg-3"><div class="card card-sm"><div class="card-body"><div class="small text-secondary">Direncanakan</div><div class="h2 mb-0 text-purple"><?=number_format($stats['planned'],0,',','.');?></div></div></div></div><div class="col-6 col-lg-3"><div class="card card-sm"><div class="card-body"><div class="small text-secondary">Total suara</div><div class="h2 mb-0"><?=number_format($stats['total'],0,',','.');?></div></div></div></div></div><div class="card admin-card"><div class="card-body"><form class="row g-2 align-items-end" method="get"><div class="col-md-4"><label class="form-label">Cari</label><input class="form-control" name="q" value="<?=html_escape($filters['q']);?>" placeholder="Judul, isi, nama, email"></div><div class="col-6 col-md-3"><label class="form-label">Jenis</label><select class="form-select" name="type"><option value="">Semua</option><?php foreach($types as $key=>$label):?><option value="<?=$key;?>" <?=$filters['type']===$key?'selected':'';?>><?=$label;?></option><?php endforeach;?></select></div><div class="col-6 col-md-2"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">Semua</option><?php foreach($statuses as $key=>$label):?><option value="<?=$key;?>" <?=$filters['status']===$key?'selected':'';?>><?=$label;?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary"><i class="ti ti-filter me-1"></i>Filter</button> <a class="btn btn-outline-secondary" href="<?=base_url('patron-feedback');?>">Reset</a></div></form></div><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>Pesan</th><th>Pengirim</th><th>Status</th><th>Dikirim</th><th></th></tr></thead><tbody><?php if(empty($items)):?><tr><td colspan="5" class="text-center text-secondary py-4">Belum ada suara pemustaka dengan filter ini.</td></tr><?php endif;?><?php foreach($items as $item):?><tr><td><div class="fw-semibold"><?=html_escape($item['subject']);?></div><div class="small text-secondary"><span class="badge bg-blue-lt text-blue me-1"><?=html_escape($types[$item['feedback_type']]??$item['feedback_type']);?></span><?=!empty($item['rating'])?' · '.$item['rating'].'/5':'';?></div><div class="small mt-1 text-truncate" style="max-width:430px"><?=html_escape($item['message']);?></div><?php if($item['suggested_author']||$item['suggested_isbn']):?><div class="small text-secondary mt-1"><?=html_escape(implode(' · ',array_filter([$item['suggested_author'],$item['suggested_isbn'],$item['suggested_format']])));?></div><?php endif;?></td><td><div><?=html_escape($item['submitter_name']?:'Anonim');?></div><div class="small text-secondary"><?=html_escape($item['submitter_email']?:$item['submitter_phone']?:'Tanpa kontak');?></div></td><td><span class="badge <?=$colors[$item['status']]??'bg-secondary-lt';?>"><?=$statuses[$item['status']]??$item['status'];?></span><?php if($item['admin_note']):?><div class="small text-secondary mt-1 text-truncate" style="max-width:200px"><?=html_escape($item['admin_note']);?></div><?php endif;?></td><td class="small"><?=date('d M Y H:i',strtotime($item['created_at']));?></td><td><?php if($can_review):?><button class="btn btn-sm btn-primary" data-bs-toggle="modal" data-bs-target="#review-<?=$item['id'];?>"><i class="ti ti-clipboard-check me-1"></i>Tindak Lanjut</button><?php endif;?></td></tr><?php if($can_review):?><div class="modal modal-blur fade" id="review-<?=$item['id'];?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><?=form_open('patron-feedback/review/'.(int)$item['id']);?><div class="modal-header"><h5 class="modal-title">Tindak Lanjut Suara Pemustaka</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="fw-bold"><?=html_escape($item['subject']);?></div><p class="text-secondary small mt-2 mb-3"><?=nl2br(html_escape($item['message']));?></p><label class="form-label">Status</label><select class="form-select mb-3" name="status"><?php foreach($statuses as $key=>$label):?><option value="<?=$key;?>" <?=$item['status']===$key?'selected':'';?>><?=$label;?></option><?php endforeach;?></select><label class="form-label">Catatan untuk pemustaka</label><textarea class="form-control" rows="4" name="admin_note" placeholder="Hasil pemeriksaan atau rencana tindak lanjut."><?=html_escape($item['admin_note']);?></textarea></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary">Simpan</button></div><?=form_close();?></div></div></div><?php endif;?><?php endforeach;?></tbody></table></div><div class="card-footer d-flex justify-content-between"><span class="small text-secondary">Total <?=number_format($pagination['total'],0,',','.');?> pesan</span><div class="btn-group"><a class="btn btn-sm btn-outline-secondary <?=$pagination['page']<=1?'disabled':'';?>" href="<?=$pageurl(max(1,$pagination['page']-1));?>">Sebelumnya</a><a class="btn btn-sm btn-outline-secondary <?=$pagination['page']>=$pagination['pages']?'disabled':'';?>" href="<?=$pageurl(min($pagination['pages'],$pagination['page']+1));?>">Berikutnya</a></div></div></div></div></div>
